class _FamilyShoppingTest1AppState extends State<FamilyShoppingTest1App> {
  Locale locale = const Locale('fa');
  bool dark = false;
  @override void initState() { super.initState(); _load(); }
  Future<void> _load() async {
    final p = await SharedPreferences.getInstance();
    if (!mounted) return;
    setState(() { locale = Locale(p.getString('locale') ?? 'fa'); dark = p.getBool('dark') ?? false; });
  }
  Future<void> setLocale(Locale l) async { final p = await SharedPreferences.getInstance(); await p.setString('locale', l.languageCode); if (mounted) setState(() => locale = l); }
  Future<void> setDark(bool v) async { final p = await SharedPreferences.getInstance(); await p.setBool('dark', v); if (mounted) setState(() => dark = v); }
  @override Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false, title: 'لیست خرید خانواده تست1', locale: locale,
    supportedLocales: const [Locale('fa'), Locale('ar'), Locale('en')],
    localizationsDelegates: const [GlobalMaterialLocalizations.delegate, GlobalWidgetsLocalizations.delegate, GlobalCupertinoLocalizations.delegate],
    theme: ThemeData(useMaterial3: true, colorScheme: ColorScheme.fromSeed(seedColor: kSeed), scaffoldBackgroundColor: const Color(0xFFF7F7FB), cardTheme: const CardThemeData(margin: EdgeInsets.zero, elevation: 0)),
    darkTheme: ThemeData(useMaterial3: true, colorScheme: ColorScheme.fromSeed(seedColor: kSeed, brightness: Brightness.dark), cardTheme: const CardThemeData(margin: EdgeInsets.zero, elevation: 0)),
    themeMode: dark ? ThemeMode.dark : ThemeMode.light,
    home: AuthGate(firebaseReady: widget.firebaseReady, onLocaleChanged: setLocale, onDarkChanged: setDark),
  );
}

