String catName(BuildContext c, Category x) { const fa=['سوپرمارکت','لبنیات','میوه و سبزی','پروتئین','نان و شیرینی','خانه','بهداشت','سایر']; const en=['Grocery','Dairy','Fruit & Veg','Protein','Bakery','Household','Health','Other']; const ar=['بقالة','ألبان','خضار وفواكه','لحوم','مخبوزات','المنزل','الصحة','أخرى']; final a=Localizations.localeOf(c).languageCode=='fa'?fa:Localizations.localeOf(c).languageCode=='ar'?ar:en; return a[x.index]; }
