class Item { final String id,name; final int qty; final bool done; final Category category; Item({required this.id,required this.name,required this.qty,required this.done,required this.category}); Map<String,dynamic> map()=>{'id':id,'name':name,'qty':qty,'done':done,'category':category.index}; factory Item.from(Map<String,dynamic> m)=>Item(id:'${m['id']??''}',name:'${m['name']??''}',qty:(m['qty'] as num?)?.toInt()??1,done:m['done']??false,category:Category.values[((m['category'] as num?)?.toInt()??7).clamp(0,7)]); }
class BuyList { final String id,name; final List<Item> items; final DateTime updated; final bool archived; BuyList({required this.id,required this.name,required this.items,required this.updated,required this.archived}); Map<String,dynamic> map()=>{'id':id,'name':name,'items':items.map((e)=>e.map()).toList(),'updated':updated.toIso8601String(),'archived':archived}; factory BuyList.from(Map<String,dynamic> m)=>BuyList(id:'${m['id']}',name:'${m['name']}',items:((m['items'] as List?)??[]).map((e)=>Item.from(Map<String,dynamic>.from(e))).toList(),updated:DateTime.tryParse('${m['updated']}')??DateTime.now(),archived:m['archived']??false); }
class FamilyMember { final String name,email,role; FamilyMember(this.name,this.email,this.role); }

class Store {
  final bool firebaseReady; final FirebaseFirestore db=FirebaseFirestore.instance; String? familyId;
  Store(this.firebaseReady);
  Future<void> load() async { final p=await SharedPreferences.getInstance(); familyId=p.getString('familyId'); }
  Future<void> saveFamily(String id) async { familyId=id; final p=await SharedPreferences.getInstance(); await p.setString('familyId',id); }
  String id()=>DateTime.now().microsecondsSinceEpoch.toString()+Random().nextInt(999).toString();
  Future<User?> user() async { if(!firebaseReady)return null; if(FirebaseAuth.instance.currentUser==null) await FirebaseAuth.instance.signInAnonymously(); return FirebaseAuth.instance.currentUser; }
  Future<void> token() async { final u=await user(); if(u==null)return; try{await FirebaseMessaging.instance.requestPermission(alert:true,badge:true,sound:true); final t=await FirebaseMessaging.instance.getToken(); await db.collection('users').doc(u.uid).set({'token':t??'','name':u.displayName??'','updatedAt':FieldValue.serverTimestamp()},SetOptions(merge:true));}catch(_){}}
  Future<String> createFamily() async { final u=await user(); if(u==null)throw Exception('Firebase'); final d=db.collection('families').doc(); await d.set({'memberIds':[u.uid],'createdAt':FieldValue.serverTimestamp()}); await saveFamily(d.id); await token(); return d.id; }
  Future<String> pairQr() async { final u=await user(); if(u==null||familyId==null)throw Exception('No family'); final code='${id()}${Random().nextInt(99999)}'; await db.collection('pairingCodes').doc(code).set({'familyId':familyId,'ownerUid':u.uid,'createdAt':FieldValue.serverTimestamp(),'expiresAt':Timestamp.fromDate(DateTime.now().add(const Duration(minutes:20)))}); return jsonEncode({'type':'family_pair','code':code}); }
  Future<void> join(String raw) async { final u=await user(); if(u==null)throw Exception('Firebase'); final j=jsonDecode(raw); final code=j['code']; final s=await db.collection('pairingCodes').doc(code).get(); if(!s.exists)throw Exception('QR invalid'); final d=s.data()!; if((d['expiresAt'] as Timestamp).toDate().isBefore(DateTime.now()))throw Exception('QR expired'); await db.collection('families').doc(d['familyId']).update({'memberIds':FieldValue.arrayUnion([u.uid]),'lastJoinCode':code}); await saveFamily(d['familyId']); await token(); }
  Stream<QuerySnapshot<Map<String,dynamic>>>? lists() => firebaseReady&&familyId!=null?db.collection('families').doc(familyId).collection('lists').orderBy('updatedAt',descending:true).snapshots():null;
  Future<void> put(BuyList l) async { if(!firebaseReady||familyId==null)return; final u=await user(); await db.collection('families').doc(familyId).collection('lists').doc(l.id).set({...l.map(),'updatedAt':FieldValue.serverTimestamp(),'updatedBy':u?.uid}); }
  Future<void> archive(BuyList l) async { final a=BuyList(id:l.id,name:l.name,items:l.items,updated:DateTime.now(),archived:true); await put(a); }
}

class AuthGate extends StatefulWidget { final bool firebaseReady; final ValueChanged<Locale> onLocaleChanged; final ValueChanged<bool> onDarkChanged; const AuthGate({super.key,required this.firebaseReady,required this.onLocaleChanged,required this.onDarkChanged}); @override State<AuthGate> createState()=>_AuthGateState(); }
