 @override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(28),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Column(children:[AppLogo(size:82),const SizedBox(height:20),Text('لیست خرید خانواده تست1',style:TextStyle(fontSize:32,fontWeight:FontWeight.w900)),const SizedBox(height:8),Text('لیست خرید، همیشه همراه خانواده',textAlign:TextAlign.center),const SizedBox(height:34),Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[Text(T.get(c,'welcome'),style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:18),if(create)TextField(controller:name,decoration:InputDecoration(labelText:T.get(c,'name'),prefixIcon:const Icon(Icons.person_outline))),if(create)const SizedBox(height:12),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:InputDecoration(labelText:T.get(c,'email'),prefixIcon:const Icon(Icons.email_outlined))),const SizedBox(height:12),TextField(controller:pass,obscureText:true,decoration:InputDecoration(labelText:T.get(c,'password'),prefixIcon:const Icon(Icons.lock_outline))),const SizedBox(height:18),SizedBox(width:double.infinity,child:FilledButton(onPressed:busy?null:go,child:Text(create?T.get(c,'create'):T.get(c,'signIn')))),TextButton(onPressed:busy?null:()=>setState(()=>create=!create),child:Text(create?T.get(c,'login'):T.get(c,'create'))),const Divider(),TextButton.icon(onPressed:widget.onGuest,icon:const Icon(Icons.person_outline),label:Text(T.get(c,'guest'))])))])))))); }
