class MainShell extends StatefulWidget { final bool firebaseReady; final ValueChanged<Locale> onLocaleChanged; final ValueChanged<bool> onDarkChanged; const MainShell({super.key,required this.firebaseReady,required this.onLocaleChanged,required this.onDarkChanged}); @override State<MainShell> createState()=>_MainShellState(); }
class _MainShellState extends State<MainShell>{ int tab=0; late Store store; List<BuyList> lists=[]; List<BuyList> history=[]; List<FamilyMember> family=[FamilyMember('شما','—','مدیر')]; StreamSubscription? sub; bool initialized=false;
 @override void initState(){super.initState(); store=Store(widget.firebaseReady); _init();}
 Future<void> _init() async { final p=await SharedPreferences.getInstance(); final raw=p.getStringList('lists')??[]; lists=raw.map((e)=>BuyList.from(jsonDecode(e))).where((x)=>!x.archived).toList(); history=raw.map((e)=>BuyList.from(jsonDecode(e))).where((x)=>x.archived).toList(); store.familyId=p.getString('familyId'); initialized=true; if(widget.firebaseReady){store.familyId=p.getString('familyId'); if(store.familyId==null)try{await store.createFamily();}catch(_){} await store.token(); sub=store.lists()?.listen((s){final r=s.docs.map((d)=>BuyList.from({...d.data(),'id':d.id})).toList(); if(mounted)setState((){lists=r.where((x)=>!x.archived).toList();history=r.where((x)=>x.archived).toList();});});} if(mounted)setState((){}); }
 Future<void> save() async { final p=await SharedPreferences.getInstance(); await p.setStringList('lists',[...lists,...history].map((e)=>jsonEncode(e.map())).toList()); }
 Future<void> put(BuyList l) async { setState((){lists=[...lists.where((x)=>x.id!=l.id),l];}); await save(); await store.put(l); }
