class ListEditor extends StatefulWidget{final BuyList list;final Future<void> Function(BuyList) onChanged;final Future<void> Function(BuyList) onArchive;const ListEditor({super.key,required this.list,required this.onChanged,required this.onArchive});@override State<ListEditor> createState()=>_ListEditorState();}
class _ListEditorState extends State<ListEditor>{late BuyList l;String filter='all';@override void initState(){super.initState();l=widget.list;} Future<void> add() async {final n=TextEditingController();final q=TextEditingController(text:'1');Category cat=Category.grocery;final ok=await showDialog<bool>(context:context,builder:(_)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:Text(T.get(c,'addItem')),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,autofocus:true,decoration:InputDecoration(labelText:T.get(c,'item'))),const SizedBox(height:12),TextField(controller:q,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:T.get(c,'qty'))),const SizedBox(height:12),DropdownButtonFormField<Category>(value:cat,items:Category.values.map((x)=>DropdownMenuItem(value:x,child:Row(children:[Icon(catIcon(x),size:20),const SizedBox(width:8),Text(catName(c,x))]))).toList(),onChanged:(x)=>set(()=>cat=x??cat),decoration:InputDecoration(labelText:T.get(c,'categories')))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:Text(T.get(c,'cancel'))),FilledButton(onPressed:()=>Navigator.pop(c,true),child:Text(T.get(c,'save')))])));if(ok==true&&n.text.trim().isNotEmpty){final item=Item(id:DateTime.now().microsecondsSinceEpoch.toString(),name:n.text.trim(),qty:int.tryParse(q.text)??1,done:false,category:cat);setState(()=>l=BuyList(id:l.id,name:l.name,items:[...l.items,item],updated:DateTime.now(),archived:false));await widget.onChanged(l);}}
 Future<void> toggle(Item x){final items=l.items.map((i)=>i.id==x.id?Item(id:i.id,name:i.name,qty:i.qty,done:!i.done,category:i.category):i).toList();l=BuyList(id:l.id,name:l.name,items:items,updated:DateTime.now(),archived:false);setState((){});return widget.onChanged(l);}
 @override Widget build(BuildContext c){final shown=l.items.where((x)=>filter=='all'||(filter=='done'&&x.done)||(filter=='todo'&&!x.done)).toList();return Scaffold(appBar:AppBar(title:Text(l.name),actions:[IconButton(onPressed:()=>widget.onArchive(l),icon:const Icon(Icons.archive_outlined))]),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:Text(T.get(c,'addItem'))),body:ListView(padding:const EdgeInsets.fromLTRB(16,10,16,100),children:[SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:[ChoiceChip(label:Text(T.get(c,'all')),selected:filter=='all',onSelected:(_)=>setState(()=>filter='all')),const SizedBox(width:8),ChoiceChip(label:Text(T.get(c,'done')),selected:filter=='done',onSelected:(_)=>setState(()=>filter='done')),const SizedBox(width:8),ChoiceChip(label:Text(T.get(c,'new')),selected:filter=='todo',onSelected:(_)=>setState(()=>filter='todo'))])),const SizedBox(height:14),if(shown.isEmpty)Padding(padding:const EdgeInsets.all(50),child:Center(child:Text(T.get(c,'empty')))) else ...shown.map((x)=>Card(margin:const EdgeInsets.only(bottom:9),child:ListTile(leading:CircleAvatar(child:Icon(catIcon(x.category),size:19)),title:Text(x.name,style:TextStyle(decoration:x.done?TextDecoration.lineThrough:null,fontWeight:FontWeight.w600)),subtitle:Text(catName(c,x.category)),trailing:Row(mainAxisSize:MainAxisSize.min,children:[Text('×${x.qty}',style:const TextStyle(fontWeight:FontWeight.bold)),Checkbox(value:x.done,onChanged:(_)=>toggle(x))])))) ]));}}

