class Scanner extends StatefulWidget{const Scanner({super.key});@override State<Scanner> createState()=>_ScannerState();}class _ScannerState extends State<Scanner>{bool done=false;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(T.get(c,'scan'))),body:MobileScanner(onDetect:(capture){if(done)return;final s=capture.barcodes.isNotEmpty?capture.barcodes.first.rawValue:null;if(s!=null){done=true;Navigator.pop(c,s);}}));}
